SELECT COUNT(*)
FROM trade t
LEFT JOIN orders_normal_orders_items onoi ON onoi.order_id = t.order_id
WHERE onoi.create_time >= #{createTimeStart}
AND onoi.create_time <= #{createTimeEnd}
AND t.trade_state IN

	#{s}

SELECT onoi.order_id AS orderId, onoi.id AS lineId
FROM trade t
LEFT JOIN orders_normal_orders_items onoi ON onoi.order_id = t.order_id
WHERE onoi.create_time >= #{createTimeStart}
AND onoi.create_time <= #{createTimeEnd}
AND t.trade_state IN

	#{s}

LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM trade t
LEFT JOIN orders_normal_orders_items onoi ON onoi.order_id = t.order_id
LEFT JOIN orders_normal_orders o ON o.order_id = t.order_id
WHERE onoi.create_time >= #{createTimeStart}
AND onoi.create_time <= #{createTimeEnd}
AND t.trade_state IN

	#{s}

AND o.order_class = 'employee_purchase'
AND o.act_id = #{actId}

SELECT onoi.order_id AS orderId, onoi.id AS lineId
FROM trade t
LEFT JOIN orders_normal_orders_items onoi ON onoi.order_id = t.order_id
LEFT JOIN orders_normal_orders o ON o.order_id = t.order_id
WHERE onoi.create_time >= #{createTimeStart}
AND onoi.create_time <= #{createTimeEnd}
AND t.trade_state IN

	#{s}

AND o.order_class = 'employee_purchase'
AND o.act_id = #{actId}
